1	import bcrypt from 'bcrypt';
2	import jwt from 'jsonwebtoken';
3	import { Request, Response, NextFunction } from 'express';
4	import crypto from 'crypto';
5	import fs from 'fs';
6	import path from 'path';
7	import { sendPasswordResetEmail } from './email-service';
8	
9	// Security Audit Log File
10	const SECURITY_LOG_DIR = path.join(process.cwd(), 'logs');
11	const SECURITY_LOG_FILE = path.join(SECURITY_LOG_DIR, 'security-audit.log');
12	
13	// Ensure logs directory exists
14	if (!fs.existsSync(SECURITY_LOG_DIR)) {
15	  fs.mkdirSync(SECURITY_LOG_DIR, { recursive: true });
16	}
17	
18	export interface User {
19	  id: number;
20	  email: string;
21	  password: string;
22	  merchantId: number;
23	  /**
24	   * `owner` holds the account (billing, plan, team); `member` is a teammate on
25	   * one of the plan's extra seats. `merchant` is the pre-team-logins spelling of
26	   * owner and is retained so old code paths still typecheck.
27	   */
28	  role: 'owner' | 'member' | 'merchant' | 'admin';
29	  /** Identity of the users row this principal came from, when there is one. */
30	  userId?: number;
31	  resetToken?: string;
32	  resetTokenExpiry?: Date;
33	  createdAt: Date;
34	}
35	
36	/** Owner-equivalent roles. Members are excluded from billing and team writes. */
37	export function isAccountOwner(user: Pick<User, 'role'> | undefined | null): boolean {
38	  return user?.role === 'owner' || user?.role === 'merchant' || user?.role === 'admin';
39	}
40	
41	/**
42	 * Claim marking a token as issued by the team-logins scheme.
43	 *
44	 * Before team logins, `userId` in a JWT was the *merchant* id and
45	 * authenticateToken ignored it entirely. Now that real `users.id` values exist,
46	 * an old token's `userId` would address a different row, so tokens without this
47	 * claim are rejected outright. The 1h TTL caps the disruption at one re-login.
48	 */
49	export const TOKEN_PRINCIPAL = 'user' as const;
50	const ADMIN_TOKEN_PRINCIPAL = 'admin' as const;
51	
52	function isMerchantUserRole(role: unknown): role is 'owner' | 'member' {
53	  return role === 'owner' || role === 'member';
54	}
55	
56	function isPositiveInteger(value: unknown): value is number {
57	  return typeof value === 'number' && Number.isSafeInteger(value) && value > 0;
58	}
59	
60	// ============================================
61	// LOGIN SECURITY - Brute Force Protection
62	// ============================================
63	interface LoginAttempt {
64	  count: number;
65	  lastAttempt: number;
66	  lockoutUntil: number | null;
67	}
68	
69	// Email-based lockout (prevents account enumeration attacks)
70	const loginAttempts = new Map<string, LoginAttempt>();
71	// IP-based rate limiting (prevents distributed attacks)
72	const ipLoginAttempts = new Map<string, LoginAttempt>();
73	
74	const MAX_LOGIN_ATTEMPTS = 5;
75	const MAX_IP_LOGIN_ATTEMPTS = 20; // Allow more attempts per IP (multiple users may share)
76	const LOCKOUT_DURATION = 15 * 60 * 1000; // 15 minutes
77	const IP_LOCKOUT_DURATION = 30 * 60 * 1000; // 30 minutes for IP-based lockout
78	const ATTEMPT_WINDOW = 60 * 60 * 1000; // 1 hour
79	
80	// Security audit logging - writes to dedicated file with PII redaction
81	export function logSecurityEvent(event: string, details: Record<string, any>) {
82	  const timestamp = new Date().toISOString();
83	  
84	  // Redact sensitive PII for audit log
85	  const redactedDetails = { ...details };
86	  if (redactedDetails.email) {
87	    // Mask email: keep first 2 chars and domain
88	    const email = redactedDetails.email;
89	    const atIndex = email.indexOf('@');
90	    if (atIndex > 2) {
91	      redactedDetails.email = email.substring(0, 2) + '***' + email.substring(atIndex);
92	    }
93	  }
94	  
95	  const logEntry = {
96	    timestamp,
97	    event,
98	    ...redactedDetails,
99	  };
100	  
101	  const logLine = JSON.stringify(logEntry) + '\n';
102	  
103	  // Write to dedicated security audit log file
104	  try {
105	    fs.appendFileSync(SECURITY_LOG_FILE, logLine);
106	  } catch (error) {
107	    // Fallback to console if file write fails, but don't expose full details
108	    console.error(`[SECURITY_LOG_ERROR] Failed to write audit log for event: ${event}`);
109	  }
110	}
111	
112	// Check if account is locked out (by email)
113	export function isAccountLocked(email: string): { locked: boolean; remainingTime?: number } {
114	  const normalizedEmail = email.toLowerCase();
115	  const attempt = loginAttempts.get(normalizedEmail);
116	  
117	  if (!attempt || !attempt.lockoutUntil) {
118	    return { locked: false };
119	  }
120	  
121	  const now = Date.now();
122	  if (now < attempt.lockoutUntil) {
123	    const remainingTime = Math.ceil((attempt.lockoutUntil - now) / 1000 / 60);
124	    return { locked: true, remainingTime };
125	  }
126	  
127	  // Lockout expired, reset
128	  loginAttempts.delete(normalizedEmail);
129	  return { locked: false };
130	}
131	
132	// Check if IP is rate limited
133	export function isIPRateLimited(ip: string): { limited: boolean; remainingTime?: number } {
134	  const attempt = ipLoginAttempts.get(ip);
135	  
136	  if (!attempt || !attempt.lockoutUntil) {
137	    return { limited: false };
138	  }
139	  
140	  const now = Date.now();
141	  if (now < attempt.lockoutUntil) {
142	    const remainingTime = Math.ceil((attempt.lockoutUntil - now) / 1000 / 60);
143	    return { limited: true, remainingTime };
144	  }
145	  
146	  // Lockout expired, reset
147	  ipLoginAttempts.delete(ip);
148	  return { limited: false };
149	}
150	
151	// Record failed login attempt (both email and IP tracking)
152	export function recordFailedLogin(email: string, ip: string): { locked: boolean; ipLimited?: boolean; attemptsRemaining?: number } {
153	  const normalizedEmail = email.toLowerCase();
154	  const now = Date.now();
155	  
156	  // Track by email
157	  let emailAttempt = loginAttempts.get(normalizedEmail);
158	  if (!emailAttempt || now - emailAttempt.lastAttempt > ATTEMPT_WINDOW) {
159	    emailAttempt = { count: 1, lastAttempt: now, lockoutUntil: null };
160	  } else {
161	    emailAttempt.count++;
162	    emailAttempt.lastAttempt = now;
163	  }
164	  
165	  // Track by IP
166	  let ipAttempt = ipLoginAttempts.get(ip);
167	  if (!ipAttempt || now - ipAttempt.lastAttempt > ATTEMPT_WINDOW) {
168	    ipAttempt = { count: 1, lastAttempt: now, lockoutUntil: null };
169	  } else {
170	    ipAttempt.count++;
171	    ipAttempt.lastAttempt = now;
172	  }
173	  
174	  logSecurityEvent('FAILED_LOGIN', { 
175	    email: normalizedEmail, 
176	    ip, 
177	    emailAttemptCount: emailAttempt.count,
178	    ipAttemptCount: ipAttempt.count 
179	  });
180	  
181	  // Check IP lockout first (affects all users from that IP)
182	  if (ipAttempt.count >= MAX_IP_LOGIN_ATTEMPTS) {
183	    ipAttempt.lockoutUntil = now + IP_LOCKOUT_DURATION;
184	    ipLoginAttempts.set(ip, ipAttempt);
185	    logSecurityEvent('IP_RATE_LIMITED', { ip, lockoutMinutes: IP_LOCKOUT_DURATION / 60000 });
186	    return { locked: false, ipLimited: true };
187	  }
188	  ipLoginAttempts.set(ip, ipAttempt);
189	  
190	  // Check email lockout
191	  if (emailAttempt.count >= MAX_LOGIN_ATTEMPTS) {
192	    emailAttempt.lockoutUntil = now + LOCKOUT_DURATION;
193	    loginAttempts.set(normalizedEmail, emailAttempt);
194	    logSecurityEvent('ACCOUNT_LOCKED', { email: normalizedEmail, ip, lockoutMinutes: LOCKOUT_DURATION / 60000 });
195	    return { locked: true };
196	  }
197	  
198	  loginAttempts.set(normalizedEmail, emailAttempt);
199	  return { locked: false, attemptsRemaining: MAX_LOGIN_ATTEMPTS - emailAttempt.count };
200	}
201	
202	// Clear failed attempts on successful login
203	export function clearFailedAttempts(email: string) {
204	  const normalizedEmail = email.toLowerCase();
205	  loginAttempts.delete(normalizedEmail);
206	  // Note: IP attempts are NOT cleared on successful login to prevent abuse
207	}
208	
209	// Cleanup old login attempts periodically
210	const loginAttemptCleanupTimer = setInterval(() => {
211	  const now = Date.now();
212	  
213	  // Clean email-based attempts
214	  const emailEntries = Array.from(loginAttempts.entries());
215	  for (const [email, attempt] of emailEntries) {
216	    if (now - attempt.lastAttempt > ATTEMPT_WINDOW && (!attempt.lockoutUntil || now > attempt.lockoutUntil)) {
217	      loginAttempts.delete(email);
218	    }
219	  }
220	  
221	  // Clean IP-based attempts
222	  const ipEntries = Array.from(ipLoginAttempts.entries());
223	  for (const [ip, attempt] of ipEntries) {
224	    if (now - attempt.lastAttempt > ATTEMPT_WINDOW && (!attempt.lockoutUntil || now > attempt.lockoutUntil)) {
225	      ipLoginAttempts.delete(ip);
226	    }
227	  }
228	}, 10 * 60 * 1000); // Clean up every 10 minutes
229	loginAttemptCleanupTimer.unref();
230	
231	export interface AuthenticatedRequest extends Request {
232	  user?: User;
233	}
234	
235	// Retained for backwards compatibility with startup and verification call sites.
236	// User rows are synchronised by the storage write that sets an owner's password.
237	export async function syncVerifiedMerchants(): Promise<void> {
238	  // no-op — authentication reads live from the users table
239	}
240	
241	export const JWT_SECRET = process.env.JWT_SECRET ?? (() => {
242	  if (process.env.NODE_ENV === 'production') {
243	    throw new Error('JWT_SECRET environment variable must be set in production');
244	  }
245	  return 'dev-only-jwt-secret-not-for-production';
246	})();
247	
248	function userRowToUser(row: {
249	  id: number;
250	  email: string;
251	  password: string;
252	  merchantId: number | null;
253	  role: string;
254	  createdAt?: Date | null;
255	}): User | null {
256	  // Admins are environment-backed, never merchant-scoped database users. Unknown
257	  // roles fail closed instead of silently inheriting member access.
258	  if (
259	    !isPositiveInteger(row.id) ||
260	    !isPositiveInteger(row.merchantId) ||
261	    !isMerchantUserRole(row.role) ||
262	    typeof row.email !== 'string' ||
263	    typeof row.password !== 'string'
264	  ) {
265	    return null;
266	  }
267	  return {
268	    id: row.id,
269	    userId: row.id,
270	    email: row.email,
271	    password: row.password,
272	    merchantId: row.merchantId,
273	    role: row.role,
274	    createdAt: row.createdAt ?? new Date(),
275	  };
276	}
277	
278	/**
279	 * Resolves a login against the `users` table — one row per person, so a seat can
280	 * be revoked without disturbing anyone else's access.
281	 *
282	 * Three gates, all of which must pass: the user row is active, the parent
283	 * merchant is verified/active, and the password matches. A disabled teammate
284	 * fails the first gate even though their password is still correct.
285	 */
286	export async function authenticateUser(email: string, password: string): Promise<User | null> {
287	  const { storage } = await import('./storage');
288	
289	  const userRow = await storage.getUserByEmail(email);
290	  if (!userRow || userRow.status !== 'active') return null;
291	
292	  const user = userRowToUser(userRow);
293	  if (!user) return null;
294	
295	  const merchant = await storage.getMerchant(user.merchantId);
296	  if (!merchant) return null;
297	  if (merchant.status !== 'verified' && merchant.status !== 'active') return null;
298	
299	  const isValid = await bcrypt.compare(password, userRow.password);
300	  if (!isValid) return null;
301	
302	  // Downgrades are normally blocked while too many seats are occupied, but this
303	  // second gate covers races, manual repairs and future migrations. The owner
304	  // always retains access so the account can remove seats or fix billing.
305	  if (user.role === 'member') {
306	    const subscription = await storage.getSubscription(user.merchantId);
307	    const seatLimit = subscription?.seatLimit;
308	    if (!isPositiveInteger(seatLimit)) return null;
309	    const seatsInUse = await storage.countSeatsInUse(user.merchantId);
310	    if (seatsInUse > seatLimit) return null;
311	  }
312	
313	  await storage.recordUserLogin(userRow.id, new Date()).catch(() => {});
314	  return user;
315	}
316	
317	export function generateToken(user: User): string {
318	  const userId = user.userId ?? user.id;
319	  if (!isPositiveInteger(userId) || typeof user.email !== 'string' || !user.email) {
320	    throw new Error('Cannot issue a token for an invalid principal');
321	  }
322	
323	  if (user.role === 'admin') {
324	    const adminEmail = process.env.ADMIN_EMAIL;
325	    if (!adminEmail || user.email.toLowerCase() !== adminEmail.toLowerCase() || user.merchantId !== 0) {
326	      throw new Error('Cannot issue an admin token for an unconfigured principal');
327	    }
328	    return jwt.sign(
329	      { principal: ADMIN_TOKEN_PRINCIPAL, userId, email: adminEmail, merchantId: 0, role: 'admin' },
330	      JWT_SECRET,
331	      { expiresIn: '1h' },
332	    );
333	  }
334	
335	  if (!isMerchantUserRole(user.role) || !isPositiveInteger(user.merchantId)) {
336	    throw new Error('Cannot issue a token without a users-row principal');
337	  }
338	
339	  return jwt.sign(
340	    {
341	      principal: TOKEN_PRINCIPAL,
342	      userId,
343	      email: user.email,
344	      merchantId: user.merchantId,
345	      role: user.role
346	    },
347	    JWT_SECRET,
348	    { expiresIn: '1h' } // 1 hour as requested
349	  );
350	}
351	
352	export function verifyToken(token: string): any {
353	  try {
354	    return jwt.verify(token, JWT_SECRET);
355	  } catch (error) {
356	    return null;
357	  }
358	}
359	
360	export async function authenticateToken(req: AuthenticatedRequest, res: Response, next: NextFunction) {
361	  const authHeader = req.headers['authorization'];
362	  const match = typeof authHeader === 'string' ? authHeader.match(/^Bearer ([^\s]+)$/i) : null;
363	
364	  if (!match) {
365	    return res.status(401).json({ message: 'Access token required' });
366	  }
367	  const token = match[1];
368	  const decoded = verifyToken(token);
369	  if (!decoded) {
370	    return res.status(403).json({ message: 'Invalid or expired token' });
371	  }
372	
373	  // A role string alone is not admin authority. Require the dedicated principal,
374	  // the configured email, and a zero merchant scope.
375	  if (decoded.role === 'admin') {
376	    const adminEmail = process.env.ADMIN_EMAIL;
377	    if (
378	      decoded.principal !== ADMIN_TOKEN_PRINCIPAL ||
379	      !adminEmail ||
380	      typeof decoded.email !== 'string' ||
381	      decoded.email.toLowerCase() !== adminEmail.toLowerCase() ||
382	      decoded.merchantId !== 0 ||
383	      !isPositiveInteger(decoded.userId)
384	    ) {
385	      return res.status(403).json({ message: 'Invalid admin session' });
386	    }
387	    req.user = {
388	      id: decoded.userId,
389	      email: adminEmail,
390	      password: '',
391	      merchantId: 0,
392	      role: 'admin',
393	      createdAt: new Date(),
394	    };
395	    return next();
396	  }
397	
398	  // Reject pre-team-logins tokens: their `userId` is a merchant id, so honouring
399	  // one would resolve the wrong users row. See TOKEN_PRINCIPAL.
400	  if (decoded.principal !== TOKEN_PRINCIPAL) {
401	    return res.status(401).json({ message: 'Session expired. Please sign in again.' });
402	  }
403	
404	  if (
405	    !isPositiveInteger(decoded.merchantId) ||
406	    !isPositiveInteger(decoded.userId) ||
407	    !isMerchantUserRole(decoded.role)
408	  ) {
409	    return res.status(404).json({ message: 'User not found' });
410	  }
411	
412	  try {
413	    const { storage } = await import('./storage');
414	    const userRow = await storage.getUserById(decoded.userId);
415	    const user = userRow ? userRowToUser(userRow) : null;
416	
417	    // Re-check the identity on every request so disabling a teammate takes effect
418	    // within the token's remaining lifetime rather than at its natural expiry.
419	    if (!userRow || !user || userRow.status !== 'active' || user.merchantId !== decoded.merchantId) {
420	      return res.status(403).json({ message: 'Access revoked' });
421	    }
422	
423	    const merchant = await storage.getMerchant(decoded.merchantId);
424	    if (merchant && (merchant.status === 'verified' || merchant.status === 'active')) {
425	      // The database role is authoritative; stale JWT role claims are ignored.
426	      req.user = user;
427	      return next();
428	    }
429	  } catch {
430	    // fall through to user not found below
431	  }
432	  return res.status(404).json({ message: 'User not found' });
433	}
434	
435	// Enable the owner's login and return the real users-row principal. The merchant
436	// hash writer synchronises/creates that owner row; re-reading it prevents Google
437	// OAuth from minting a token whose uid is accidentally the merchant id.
438	export async function createUser(email: string, password: string, merchantId: number, role: 'merchant' | 'admin' = 'merchant'): Promise<User> {
439	  if (role === 'admin') {
440	    throw new Error('Admin identities cannot be created in the merchant users table');
441	  }
442	
443	  const { storage } = await import('./storage');
444	  const merchant = await storage.getMerchant(merchantId);
445	  if (!merchant) {
446	    throw new Error(`Cannot create login for unknown merchant ${merchantId}`);
447	  }
448	  if (merchant.email.trim().toLowerCase() !== email.trim().toLowerCase()) {
449	    throw new Error(`Cannot create login with an email that does not match merchant ${merchantId}`);
450	  }
451	
452	  const passwordHash = merchant.passwordHash || await bcrypt.hash(password, 12);
453	  const updated = await storage.updateMerchantPasswordHash(merchantId, passwordHash);
454	  if (!updated) {
455	    throw new Error(`Failed to enable login for merchant ${merchantId}`);
456	  }
457	
458	  const userRow = await storage.getUserByEmail(merchant.email);
459	  const user = userRow ? userRowToUser(userRow) : null;
460	  if (!userRow || !user || userRow.status !== 'active' || user.role !== 'owner' || user.merchantId !== merchantId) {
461	    throw new Error(`Merchant ${merchantId} does not have a unique active owner login`);
462	  }
463	  return user;
464	}
465	
466	export async function getUserByEmail(email: string): Promise<User | undefined> {
467	  const { storage } = await import('./storage');
468	  const userRow = await storage.getUserByEmail(email);
469	  return userRow ? userRowToUser(userRow) ?? undefined : undefined;
470	}
471	
472	// Password reset functionality
473	export function generateResetToken(): string {
474	  return crypto.randomBytes(32).toString('hex');
475	}
476	
477	function hashResetToken(token: string): string {
478	  return crypto.createHash('sha256').update(token, 'utf8').digest('hex');
479	}
480	
481	function resetEligible(user: {
482	  merchantId: number | null;
483	  role: string;
484	  status: string;
485	  resetTokenExpiry?: Date | null;
486	}, now: Date): boolean {
487	  const expiry = user.resetTokenExpiry ? new Date(user.resetTokenExpiry).getTime() : Number.NaN;
488	  return isPositiveInteger(user.merchantId)
489	    && isMerchantUserRole(user.role)
490	    && user.status === 'active'
491	    && Number.isFinite(expiry)
492	    && expiry > now.getTime();
493	}
494	
495	export async function requestPasswordReset(email: string, baseUrl?: string): Promise<boolean> {
496	  try {
497	    const { storage } = await import('./storage');
498	    const user = await storage.getUserByEmail(email);
499	    if (!user || !isPositiveInteger(user.merchantId) || !isMerchantUserRole(user.role) || user.status !== 'active') {
500	      return true; // Do not reveal whether a usable login exists.
501	    }
502	
503	    const resetToken = generateResetToken();
504	    const resetTokenExpiry = new Date(Date.now() + 60 * 60 * 1000);
505	    await storage.setUserResetToken(user.id, hashResetToken(resetToken), resetTokenExpiry);
506	
507	    return await sendPasswordResetEmail(user.email, resetToken, baseUrl);
508	  } catch (error) {
509	    console.error('Failed to process password reset request:', error);
510	    return false;
511	  }
512	}
513	
514	export async function resetPassword(token: string, newPassword: string): Promise<boolean> {
515	  try {
516	    const { storage } = await import('./storage');
517	    const tokenHash = hashResetToken(token);
518	    const now = new Date();
519	    const candidate = await storage.getUserByResetToken(tokenHash);
520	    if (!candidate || !resetEligible(candidate, now)) return false;
521	
522	    const hashedPassword = await bcrypt.hash(newPassword, 12);
523	    const updated = await storage.resetUserPasswordByToken(tokenHash, hashedPassword, now);
524	    return !!updated && isMerchantUserRole(updated.role) && updated.status === 'active';
525	  } catch (error) {
526	    console.error('Failed to reset password:', error);
527	    return false;
528	  }
529	}
530	
531	export async function validateResetToken(token: string): Promise<boolean> {
532	  try {
533	    const { storage } = await import('./storage');
534	    const user = await storage.getUserByResetToken(hashResetToken(token));
535	    return !!user && resetEligible(user, new Date());
536	  } catch (error) {
537	    console.error('Failed to validate reset token:', error);
538	  }
539	  return false;
540	}

