139	  () => import("@/desktop/pages/retail-settings"),
140	  () => import("@/desktop/pages/property-home"),
141	  () => import("@/desktop/pages/property-clients"),
142	  () => import("@/desktop/pages/property-terminal"),
143	  () => import("@/desktop/pages/property-analytics"),
144	  () => import("@/desktop/pages/property-settings"),
145	  () => import("@/desktop/pages/trades-home"),
146	  () => import("@/desktop/pages/trades-clients"),
147	  () => import("@/desktop/pages/trades-terminal"),
148	  () => import("@/desktop/pages/trades-analytics"),
149	  () => import("@/desktop/pages/trades-settings"),
150	  () => import("@/desktop/DesktopLegacyPage"),
151	];
