153	/* Sequential (not Promise.all) so warming never competes with the page's own
154	   data fetches for bandwidth; each chunk waits for the next idle slice. */
155	function useRoutePreload(enabled: boolean, deviceClass: DeviceClass) {
156	  useEffect(() => {
157	    if (!enabled) return;
158	    const routes = deviceClass === "mobile" ? MOBILE_PRELOAD_ROUTES : DESKTOP_PRELOAD_ROUTES;
159	    let stopped = false;
160	    let i = 0;
161	    const idle = (cb: () => void) =>
162	      "requestIdleCallback" in window
163	        ? (window as any).requestIdleCallback(cb, { timeout: 2000 })
164	        : setTimeout(cb, 250);
165	    const next = () => {
166	      if (stopped || i >= routes.length) return;
167	      routes[i++]()
168	        .catch(() => {}) // offline / chunk 404 — the lazy() route will surface it if actually visited
169	        .finally(() => idle(next));
170	    };
171	    // Head start for first paint + the auth check before saturating the pipe.
172	    const t = setTimeout(() => idle(next), 1000);
173	    return () => { stopped = true; clearTimeout(t); };
174	  }, [deviceClass, enabled]);
175	}
176	
177	/**
178	 * The route-level full-screen loader, for mobile and public routes.
179	 *
180	 * `data-testid` marks it as exactly that: the transition probes gate on this
181	 * element appearing, and must not confuse it with a page's own content spinner,
182	 * which shares the `animate-spin` utility class but covers nothing.
183	 */
184	function PageLoader() {
185	  return (
186	    <div data-testid="page-loader" className="min-h-screen flex items-center justify-center" style={{ background: "#060D1F" }}>
187	      <div className="w-8 h-8 border-2 border-[#00DFC8] border-t-transparent rounded-full animate-spin" />
188	    </div>
189	  );
190	}
191	
192	// Auth is checked ONCE at app load and cached here. ProtectedRoute reads from
193	// this context so navigating between protected routes never shows a loader or
194	// makes a redundant API call — both of which would destroy page transitions.
195	type AuthData = {
196	  isAuthenticated: boolean;
197	  merchantId?: string | null;
198	  role?: string | null;
199	  onboardingCompleted?: boolean | null;
200	  gstRegistered?: boolean;
201	  tradeGstMode?: "inclusive" | "exclusive";
202	};
203	
204	const AuthContext = createContext<{ auth: AuthData | null; isChecking: boolean }>({
205	  auth: null,
206	  isChecking: true,
207	});
208	
209	function AuthProvider({ children }: { children: React.ReactNode }) {
210	  const [auth, setAuth] = useState<AuthData | null>(null);
211	  const [isChecking, setIsChecking] = useState(true);
212	
213	  useEffect(() => {
214	    const token = localStorage.getItem("authToken");
215	    if (!token) {
216	      setAuth({ isAuthenticated: false });
217	      setIsChecking(false);
218	      return;
219	    }
220	    fetch('/api/auth/me', { headers: { Authorization: `Bearer ${token}` } })
221	      .then(async r => {
222	        if (r.ok) {
223	          const data = await r.json();
224	          setAuth({
225	            isAuthenticated: true,
226	            merchantId: data?.user?.merchantId ?? null,
227	            role: data?.user?.role ?? null,
228	            onboardingCompleted: data?.user?.onboardingCompleted ?? null,
229	            gstRegistered: data?.user?.gstRegistered ?? false,
230	            tradeGstMode: data?.user?.tradeGstMode === "exclusive" ? "exclusive" : "inclusive",
231	          });
232	        } else {
233	          localStorage.removeItem("authToken");
234	          localStorage.removeItem("user");
235	          localStorage.removeItem("merchantId");
236	          setAuth({ isAuthenticated: false });
237	        }
238	      })
239	      .catch(() => {
240	        localStorage.removeItem("authToken");
241	        localStorage.removeItem("user");
242	        localStorage.removeItem("merchantId");
243	        setAuth({ isAuthenticated: false });
244	      })
245	      .finally(() => setIsChecking(false));
246	  }, []);
247	
248	  return <AuthContext.Provider value={{ auth, isChecking }}>{children}</AuthContext.Provider>;
249	}
250	
251	function ProtectedRoute({ children, skipOnboardingCheck = false, tutorialPage }: {
252	  children: React.ReactNode;
253	  skipOnboardingCheck?: boolean;
254	  tutorialPage?: TutorialPageKey;
255	}) {
256	  const [, setLocation] = useLocation();
257	  const { auth, isChecking } = useContext(AuthContext);
258	
259	  useEffect(() => {
260	    if (isChecking || !auth) return;
261	    if (!auth.isAuthenticated) {
262	      const returnTo = encodeURIComponent(window.location.pathname + window.location.search);
263	      setLocation(`/login?returnTo=${returnTo}`);
264	      return;
265	    }
266	    if (
267	      !skipOnboardingCheck &&
268	      auth.merchantId &&
269	      auth.role !== 'admin' &&
270	      auth.onboardingCompleted === false
271	    ) {
272	      setLocation("/onboarding");
273	    }
274	  }, [isChecking, auth, skipOnboardingCheck, setLocation]);
275	
276	  if (isChecking) return <PageLoader />;
277	  if (!auth?.isAuthenticated) return null;
278	  if (!skipOnboardingCheck && auth.merchantId && auth.role !== 'admin' && auth.onboardingCompleted === false) return null;
279	
280	  return tutorialPage
281	    ? <TutorialPageBoundary pageKey={tutorialPage}>{children}</TutorialPageBoundary>
282	    : <>{children}</>;
283	}
