285	function AdminProtectedRoute({ children }: { children: React.ReactNode }) {
286	  const [isAuthenticated, setIsAuthenticated] = useState(false);
287	  const [isChecking, setIsChecking] = useState(true);
288	
289	  useEffect(() => {
290	    const checkAdminAuth = async () => {
291	      const token = localStorage.getItem("adminAuthToken");
292	      if (!token) {
293	        setIsAuthenticated(false);
294	        setIsChecking(false);
295	        window.location.href = "/login";
296	        return;
297	      }
298	      try {
299	        const response = await fetch("/api/admin/auth/me", {
300	          headers: { Authorization: `Bearer ${token}` },
301	        });
302	        if (response.ok) {
303	          setIsAuthenticated(true);
304	        } else {
305	          localStorage.removeItem("adminAuthToken");
306	          localStorage.removeItem("adminUser");
307	          setIsAuthenticated(false);
308	          window.location.href = "/login";
309	        }
310	      } catch (error) {
311	        localStorage.removeItem("adminAuthToken");
312	        localStorage.removeItem("adminUser");
313	        setIsAuthenticated(false);
314	        window.location.href = "/login";
315	      }
316	      setIsChecking(false);
317	    };
318	    checkAdminAuth();
319	  }, []);
320	
321	  if (isChecking) return <PageLoader />;
322	  return isAuthenticated ? <>{children}</> : null;
323	}
