325	function GA4PageTracker() {
326	  const [location] = useLocation();
327	  useEffect(() => {
328	    if (typeof window !== 'undefined' && (window as any).gtag) {
329	      (window as any).gtag('event', 'page_view', {
330	        page_path: redactCustomerPaymentAddress(location),
331	        page_title: document.title,
332	      });
333	    }
334	  }, [location]);
335	  return null;
336	}
