345	type MerchantMode = "retail" | "property" | "trades";
346	
347	const RETAIL_MODE_PATHS = new Set(["/dashboard", "/stock", "/terminal", "/transactions"]);
348	
349	function merchantModeForLocation(location: string): MerchantMode {
350	  if (location.startsWith("/property")) return "property";
351	  if (location.startsWith("/trades")) return "trades";
352	  if (RETAIL_MODE_PATHS.has(location)) return "retail";
353	  try {
354	    const stored = localStorage.getItem("taptMode");
355	    if (stored === "property" || stored === "trades" || stored === "retail") return stored;
356	  } catch {
357	    // Storage can be unavailable in privacy-restricted browser contexts.
358	  }
359	  return "retail";
360	}
