362	function Router({ deviceClass }: { deviceClass: DeviceClass }) {
363	  const [location] = useLocation();
364	  const merchantMode = merchantModeForLocation(location);
365	
366	  if (location === "/") {
367	    return (
368	      <>
369	        <GA4PageTracker />
370	        {isPwaStandalone() ? <AppLogin /> : <LandingPage />}
371	      </>
372	    );
373	  }
374	
375	  /* Tablet/desktop app screens keep a persistent chrome and deliberately skip
376	     PageTransition: that wrapper keys a motion.div on the location, so the frame
377	     inside it was torn down and rebuilt on every hop, and its mode="wait" exit
378	     spends 220ms on a blank screen before the destination even mounts. Here the
379	     frame + header + nav stay mounted and only the page slot swaps — the
380	     incoming page's own cascade is the transition. */
381	  if (deviceClass !== "mobile") {
382	    const chromeRoute = desktopChromeForLocation(location, merchantMode);
383	    if (chromeRoute) {
384	      return (
385	        <>
386	          <GA4PageTracker />
387	          {/* Outer boundary covers only the chrome's own chunk on cold load;
388	              once resolved it stays mounted, so navigation never suspends here
389	              and the frame cannot blink between screens. */}
390	          <Suspense fallback={<DesktopPageFallback />}>
391	            <DesktopChrome deviceClass={deviceClass} route={chromeRoute}>
392	              <Suspense fallback={<DesktopPageFallback />}>
393	                {/* Keyed on the screen, not the raw location, so the cascade
394	                    replays whenever the user lands on a different screen but a
395	                    one-shot param (?quick=1) or an id segment does not throw away
396	                    a screen the user is already on. */}
397	                <RouteTable
398	                  key={`${chromeRoute.vertical}/${chromeRoute.page}`}
399	                  location={location}
400	                  deviceClass={deviceClass}
401	                  merchantMode={merchantMode}
402	                />
403	              </Suspense>
404	            </DesktopChrome>
405	          </Suspense>
406	        </>
407	      );
408	    }
409	  }
410	
411	  return (
412	    <PageTransition>
413	      {/* Pin the Switch to the wrapper's location — matching from context would
414	          let the exiting page re-render as the destination during the exit
415	          animation (a double mount that eats one-shot params like ?quick=1). */}
416	      {(transitionLocation) => (
417	        <>
418	          <GA4PageTracker />
419	          <Suspense fallback={<PageLoader />}>
420	            <RouteTable
421	              location={transitionLocation}
422	              deviceClass={deviceClass}
423	              merchantMode={merchantMode}
424	            />
425	          </Suspense>
426	        </>
427	      )}
428	    </PageTransition>
429	  );
430	}
