592	function AppRoutes() {
593	  // Only warm app chunks for signed-in merchants — marketing visitors on the
594	  // landing page shouldn't download the entire app in the background.
595	  const { auth } = useContext(AuthContext);
596	  const deviceClass = useDeviceClass();
