599	  return (
600	    <TutorialProvider enabled={tutorialEnabled}>
601	      <Router deviceClass={deviceClass} />
602	      {deviceClass === "mobile" && <BottomNavigation />}
603	    </TutorialProvider>
604	  );
605	}
