/**
 * JSX Syntax Smoke Tests
 * 
 * This test file imports all page components to catch JSX syntax errors early.
 * If any component has JSX syntax errors, the test will fail during the import phase.
 * This acts as an early warning system for broken JSX before deployment.
 */

// Dynamic imports to test JSX syntax - syntax errors will cause import failures
import { render, screen } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { NotificationProvider } from '@/components/notification-system';
import { TooltipProvider } from '@/components/ui/tooltip';
import { TutorialProvider } from '@/features/tutorial/tutorial';

// Test wrapper for React Query. NotificationProvider/TooltipProvider are required
// by the terminal pages (useNotifications / tooltip) or they throw at render.
const createTestWrapper = () => {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: { retry: false },
      mutations: { retry: false },
    },
  });

  return function TestWrapper({ children }: { children: React.ReactNode }) {
    return (
      <QueryClientProvider client={queryClient}>
        <TutorialProvider enabled={false}>
          <NotificationProvider>
            <TooltipProvider>
              {children}
            </TooltipProvider>
          </NotificationProvider>
        </TutorialProvider>
      </QueryClientProvider>
    );
  };
};

=== setup ===
const { TextEncoder, TextDecoder } = require('util');

require('@testing-library/jest-dom');

global.TextEncoder = TextEncoder;
global.TextDecoder = TextDecoder;

// Mock window.matchMedia
Object.defineProperty(window, 'matchMedia', {
  writable: true,
  value: jest.fn().mockImplementation(query => ({
    matches: false,
    media: query,
    onchange: null,
    addListener: jest.fn(), // deprecated
    removeListener: jest.fn(), // deprecated
    addEventListener: jest.fn(),
    removeEventListener: jest.fn(),
    dispatchEvent: jest.fn(),
  })),
});

// Mock EventSource — jsdom has no SSE, and pages that call sseClient.connect()
// (customer-payment, merchant-terminal*) would otherwise throw "EventSource is
// not defined" at render.
global.EventSource = class EventSource {
  constructor() {
    this.readyState = 0;
    this.onopen = null;
    this.onmessage = null;
    this.onerror = null;
  }
  addEventListener() {}
  removeEventListener() {}
  close() {}
};

// Mock IntersectionObserver
global.IntersectionObserver = class IntersectionObserver {
  constructor() {}
  disconnect() {}
  observe() {}
  unobserve() {}
};

// Mock ResizeObserver
global.ResizeObserver = class ResizeObserver {
  constructor() {}
  disconnect() {}
  observe() {}
  unobserve() {}
};

// Mock localStorage
const localStorageMock = {
  getItem: jest.fn(),
  setItem: jest.fn(),
  removeItem: jest.fn(),
  clear: jest.fn(),
};
global.localStorage = localStorageMock;

// Mock sessionStorage
global.sessionStorage = localStorageMock;

// Mock fetch for API calls
global.fetch = jest.fn();

// Mock crypto for secure random generation
Object.defineProperty(global, 'crypto', {
  value: {
    randomUUID: () => '00000000-0000-0000-0000-000000000000',
  },
});

// Mock URL.createObjectURL
global.URL.createObjectURL = jest.fn();
global.URL.revokeObjectURL = jest.fn();

// Suppress console errors during tests unless they're actual test failures
const originalError = console.error;
beforeAll(() => {
  console.error = (...args) => {
    if (
      typeof args[0] === 'string' &&
      args[0].includes('Warning: ReactDOM.render is no longer supported')
    ) {
      return;
    }
    originalError.call(console, ...args);
  };
});

afterAll(() => {
  console.error = originalError;
});

